export const ModelSupportInvestigationModal__evidence_readiness_summary = ({ implementationReadyCount, partialCount, insufficientCount, notObservedCount }: { implementationReadyCount: number; partialCount: number; insufficientCount: number; notObservedCount: number }): string => `${implementationReadyCount} ${implementationReadyCount === 1 ? 'listo para implementación' : 'listos para implementación'}, ${partialCount} ${partialCount === 1 ? 'parcial' : 'parciales'}, ${insufficientCount} ${insufficientCount === 1 ? 'insuficiente' : 'insuficientes'}, ${notObservedCount} ${notObservedCount === 1 ? 'no observado' : 'no observados'}`;
